-- Ingredient library expansion: 71 widely available ingredients, chosen to work well with what is already in the library.
--
-- What is added (all are sold in many regions, and the table is shared by every user):
--   preservatives and boosters   phenoxyethanol, benzyl alcohol, sorbic acid, benzoic acid, glyceryl caprylate
--   humectants                   honey, xylitol
--   carrier oils                 sesame, safflower, hazelnut, peach kernel, black seed, pumpkin seed, sea buckthorn, baobab, kukui,
--                                tamanu, pomegranate, prickly pear, flaxseed
--   waxes and esters             rice bran wax, sunflower wax, dicaprylyl ether, propylheptyl caprylate
--   emulsifiers                  sodium stearoyl lactylate, PGPR (for water-in-oil), polyglyceryl-3 methylglucose distearate
--   thickeners                   cellulose gum, alginate, carrageenan, konjac, locust bean gum, pectin, agar, pullulan, fumed silica,
--                                hectorite, gum arabic
--   surfactants                  sodium cocoamphoacetate, cocamidopropyl hydroxysultaine
--   actives and botanicals       ascorbyl palmitate, marshmallow root, amla, hibiscus, hydrolyzed rice protein
--   UV filters                   octisalate, Uvinul A Plus, ethylhexyl triazone
--   essential oils and hydrosols 14 essential oils, 3 hydrosols
--   others                       two pigments, rice powder, zinc ricinoleate, potassium alum, sodium gluconate
--
-- Every new row fills in the claim flags (vegan, sulfate, silicone, paraben, fragrance, COSMOS, comedogenic rating) so
-- marketing claims are checked correctly. Where an ingredient's COSMOS status is not certain it is marked not compliant,
-- so the claim check asks you to verify rather than approving it. CAS numbers are only given where they are certain.
--
-- Also fixes one claims error: the "(and)" row of Euxyl PE 9010 was marked as not vegan while its twin row was vegan.
--
-- A row is only added when no ingredient with the same INCI name and trade name exists yet, and the Euxyl fix only
-- applies while it is still wrong, so this is safe to run more than once.

insert into public.ingredients (id, inci_name, trade_name, function, min_usage_pct, max_usage_pct, cas_number, solubility, ionic_charge, physical_state, optimal_ph_min, optimal_ph_max, max_heating_temp_c, is_vegan, is_cosmos, cost_category, description, common_uses, is_sulfate, is_silicone, is_paraben, is_fragrance, cosmos_compliant, comedogenic_rating, default_min_usage, default_max_usage, notes)
select gen_random_uuid(), 'Phenoxyethanol', 'Phenoxyethanol', 'Preservative', 0.3, 1, '122-99-6', 'water', 'non-ionic', 'liquid', 3, 10, 85, true, false, 'low', 'Widely available broad-spectrum preservative, strongest against bacteria. Allowed up to 1% in the EU.', 'Lotions, creams, serums, cleansers', false, false, false, false, false, 0, 0.5, 1, 'Add during the cool-down. Stronger against bacteria than mold, so many formulas pair it with ethylhexylglycerin or a mold inhibitor such as sodium dehydroacetate.'
 where not exists (select 1 from public.ingredients i where lower(i.inci_name) = lower('Phenoxyethanol') and lower(i.trade_name) = lower('Phenoxyethanol'));

insert into public.ingredients (id, inci_name, trade_name, function, min_usage_pct, max_usage_pct, cas_number, solubility, ionic_charge, physical_state, optimal_ph_min, optimal_ph_max, max_heating_temp_c, is_vegan, is_cosmos, cost_category, description, common_uses, is_sulfate, is_silicone, is_paraben, is_fragrance, cosmos_compliant, comedogenic_rating, default_min_usage, default_max_usage, notes)
select gen_random_uuid(), 'Benzyl Alcohol', 'Benzyl Alcohol', 'Preservative', 0.5, 1, '100-51-6', 'water', 'non-ionic', 'liquid', 3, 8, 60, true, true, 'low', 'Preservative that mainly protects against bacteria and some yeasts. Accepted in natural and COSMOS formulas.', 'Lotions, shampoos, natural creams', false, false, false, false, true, 0, 0.6, 1, 'Weak against mold on its own: pair it with dehydroacetic acid or a sorbate (Geogard 221 does this). Allowed up to 1% in the EU and is also on the EU list of fragrance allergens.'
 where not exists (select 1 from public.ingredients i where lower(i.inci_name) = lower('Benzyl Alcohol') and lower(i.trade_name) = lower('Benzyl Alcohol'));

