 where not exists (select 1 from public.ingredients i where lower(i.inci_name) = lower('Zinc Ricinoleate') and lower(i.trade_name) = lower('Zinc Ricinoleate'));

insert into public.ingredients (id, inci_name, trade_name, function, min_usage_pct, max_usage_pct, cas_number, solubility, ionic_charge, physical_state, optimal_ph_min, optimal_ph_max, max_heating_temp_c, is_vegan, is_cosmos, cost_category, description, common_uses, is_sulfate, is_silicone, is_paraben, is_fragrance, cosmos_compliant, comedogenic_rating, default_min_usage, default_max_usage, notes)
select gen_random_uuid(), 'Potassium Alum', 'Alum (Potassium Alum)', 'Deodorant Active', 1, 10, '7784-24-9', 'water', 'non-ionic', 'powder', null, null, 100, true, true, 'low', 'Natural mineral salt with an antibacterial, astringent effect used in crystal deodorants and sprays.', 'Deodorant sprays, aftershaves, astringent toners', false, false, false, false, true, 0, 3, 8, 'Acidic (pH about 3-4 in water) and can irritate sensitive or broken skin. Its salt content collapses carbomer gels.'
 where not exists (select 1 from public.ingredients i where lower(i.inci_name) = lower('Potassium Alum') and lower(i.trade_name) = lower('Alum (Potassium Alum)'));

insert into public.ingredients (id, inci_name, trade_name, function, min_usage_pct, max_usage_pct, cas_number, solubility, ionic_charge, physical_state, optimal_ph_min, optimal_ph_max, max_heating_temp_c, is_vegan, is_cosmos, cost_category, description, common_uses, is_sulfate, is_silicone, is_paraben, is_fragrance, cosmos_compliant, comedogenic_rating, default_min_usage, default_max_usage, notes)
select gen_random_uuid(), 'Sodium Gluconate', 'Sodium Gluconate', 'Chelating Agent', 0.1, 0.5, '527-07-1', 'water', 'anionic', 'powder', null, null, 100, true, true, 'low', 'Food-grade, widely available chelator made by fermentation.', 'Water-based creams, lotions, cleansers', false, false, false, false, true, 0, 0.1, 0.3, 'Works best at neutral to alkaline pH. In acidic formulas, GLDA or sodium phytate chelate better.'
 where not exists (select 1 from public.ingredients i where lower(i.inci_name) = lower('Sodium Gluconate') and lower(i.trade_name) = lower('Sodium Gluconate'));

-- Claims fix: phenoxyethanol and ethylhexylglycerin are both synthetic and vegan
update public.ingredients set is_vegan = true
 where trade_name = 'Euxyl PE 9010' and inci_name = 'Phenoxyethanol (and) Ethylhexylglycerin' and is_vegan = false;
